function merge(base,input){const out={...base,...input};for(const k of ['player','combat','settings','map'])out[k]={...base[k],...(input?.[k]||{})};out.player.trait={...base.player.trait,...(input?.player?.trait||input?.trait||{})};out.player.stats={...BASE_STATS,...(input?.player?.stats||{})};out.player.specialStats={...SPECIAL_DEFAULTS,...(input?.player?.specialStats||input?.specialStats||{})};out.player.initialStats={...out.player.stats,...(input?.player?.initialStats||{})};out.player.growthProfile={...BASE_STATS,...(input?.player?.growthProfile||{})};out.player.statGrowth={level:{...(input?.player?.statGrowth?.level||{})},chronicle:{...(input?.player?.statGrowth?.chronicle||{})}};out.settings.statSections={...base.settings.statSections,...(input?.settings?.statSections||{})};out.settings.sheetSync={...base.settings.sheetSync,...(input?.settings?.sheetSync||{})};out.settings.ruleReminder={...base.settings.ruleReminder,...(input?.settings?.ruleReminder||{})};out.map.current={...base.map.current,...(input?.map?.current||{})};out.map.places={...(input?.map?.places||{})};out.inventory=(Array.isArray(out.inventory)?out.inventory:[]).map((x,i)=>typeof x==='string'?{id:`legacy_item_${i}`,name:x,description:'',grade:'일반',quantity:1,type:'기타',usable:false}:normalInventory(x,i));return out}
function allSaves(){try{return JSON.parse(localStorage.getItem(SAVES_KEY)||'{}')}catch{return{}}}
