function save(rerender=true){recalculateResources();if(activeSaveId){const saves=allSaves();state._savedAt=Date.now();saves[activeSaveId]=clone(state);writeSaves(saves);localStorage.setItem(ACTIVE_KEY,activeSaveId)}localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(rerender)render()}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function pct(v,m){return Math.max(0,Math.min(100,(Number(v)||0)/(Number(m)||1)*100))}
function expRequired(level){level=Number(level)||1;return level>=MAX_LEVEL?0:EXP[level]||30000}
function essenceSlotsFor(level){return Math.min(15,1+Math.max(0,Math.floor(((Number(level)||1)-1)/3)))}
function uid(prefix){return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,7)}`}
function normalItem(x,kind='item'){return{id:x.id||uid(kind),name:x.name||'이름 없음',description:x.description||'',grade:GRADES.includes(x.grade)?x.grade:'일반',stats:x.stats||{},...x}}
function normalInventory(x={},index=0){return{id:x.id||uid('item'),name:x.name||x.title||'이름 없는 소지품',description:x.description||x.desc||'',grade:GRADES.includes(x.grade)?x.grade:'일반',quantity:Math.max(1,Number(x.quantity??x.qty)||1),type:x.type||'기타',effect:x.effect||'',usable:!!x.usable,...x}}
function statsText(stats={}){const rows=Object.entries(stats);return rows.length?rows.map(([k,v])=>`<span>${esc(k)}</span><b>${Number(v)>0?'+':''}${esc(v)}</b>`).join(''):'<small>추가 스탯 없음</small>'}
