function resolvedSpeakers(){return(state.speakers||[]).slice(0,5).map(entry=>{const ref=state.characters.find(c=>c.id===entry?.id);return ref?{...ref,...entry,portrait:entry.portrait||ref.portrait||'',name:entry.name||ref.name,role:entry.role||ref.role||ref.introduction||''}:entry}).filter(Boolean)}
function renderSpeakers(){const list=resolvedSpeakers(),activeId=state.activeSpeakerId||list.find(x=>x.active)?.id||list.at(-1)?.id;$('#speakerRow').innerHTML=list.length?list.map(c=>`<article class="speaker-card ${c.id===activeId?'active':''}"><div class="speaker-asset">${c.portrait?`<img src="${esc(c.portrait)}" alt="${esc(c.name||'대화 인물')}">`:esc(c.asset||`(${c.name||'인물'})`)}</div><strong>${esc(c.name||'이름 없음')}</strong><small>${esc(c.role||'')}</small></article>`).join(''):'<div class="empty-speaker">현재 대화에 참여한 인물이 없습니다.</div>'}
function renderMap(){const view=state.map?.view==='capital'?'capital':'continent',nodes=view==='capital'?CAPITAL_NODES:MAP_REGIONS,current=state.map?.current||{},place=state.map?.places?.[current.locationId],marker=place&&place.mapView===view?`<div class="current-map-marker" style="left:${place.x}%;top:${place.y}%"><i>◆</i><span>${esc(current.name||'현재 위치')}</span></div>`:'';$('#mapCanvas').innerHTML=`<div class="map-left ${view}" style="background-image:url('assets/maps/${view==='capital'?'kingdom':'continent'}.png')">${nodes.map(n=>`<button class="map-node" data-map-node="${n.id}" style="left:${n.x}%;top:${n.y}%"><i>${n.icon}</i><span>${esc(n.name)}</span></button>`).join('')}${marker}${view==='capital'?'<button class="map-return" id="mapReturn">← 대륙 지도로</button>':''}</div><div class="map-fog"></div><div class="map-dungeon" style="background-image:url('assets/maps/dungeon.png')"><button class="dungeon-label" data-map-node="dungeon"><b>◆ 대던전</b><small>THE GREAT DUNGEON</small></button>${place?.mapView==='dungeon'?`<div class="current-map-marker dungeon-current" style="left:${place.x}%;top:${place.y}%"><i>◆</i><span>${esc(current.name)}</span></div>`:''}</div>`;document.querySelectorAll('[data-map-node]').forEach(b=>b.onclick=()=>selectMapNode(b.dataset.mapNode));$('#mapReturn')?.addEventListener('click',()=>{state.map.view='continent';save()});const info=$('#mapInfo');info.innerHTML=`<small>CURRENT LOCATION</small><strong>${esc(current.name||state.location||'장소 미정')}</strong><p>${esc(current.description||'지역 표식을 선택하면 이곳에 설명이 기록됩니다.')}</p>`}
function selectMapNode(id){const node=[...MAP_REGIONS,...CAPITAL_NODES].find(n=>n.id===id);if(!node)return;if(node.child==='capital'){state.map.view='capital';save();return}$('#mapInfo').innerHTML=`<small>${state.map.view==='capital'?'CAPITAL DISTRICT':'REGION'}</small><strong>${esc(node.name)}</strong><p>${esc(node.description)}</p>`}
function render(){const p=state.player,need=expRequired(p.level);$('#playerName').textContent=p.name;$('#playerMeta').textContent=`Lv. ${p.level} · ${p.title}`;$('#playerAvatar').innerHTML=p.portrait?`<img src="${esc(p.portrait)}" alt="${esc(p.name)}">`:esc((p.name||'?')[0]);$('#locationText').textContent=$('#mapLocation').textContent=state.location;$('#goldText').textContent=`소지금 ${Number(state.gold||0).toLocaleString('ko-KR')} G`;$('#dayText').textContent=`DAY ${state.day||1}`;for(const [bar,val,max,text] of [['hpBar',p.hp,p.maxHp,'hpText'],['spBar',p.sp,p.maxSp,'spText']]){$('#'+bar).style.width=pct(val,max)+'%';$('#'+text).textContent=`${val} / ${max}`}$('#expBar').style.width=p.level>=MAX_LEVEL?'100%':pct(p.exp,need)+'%';$('#expText').textContent=p.level>=MAX_LEVEL?'MAX':`${p.exp||0} / ${need}`;renderSpeakers();renderMap();if(activeTab&&activeTab!=='playerProfile'&&!$('#modalBackdrop').classList.contains('hidden'))showTab(activeTab)}
const labels={people:'인물',equipment:'장비',essence:'정수',inventory:'소지품',settings:'설정',stats:'스탯',trait:'특성',skills:'스킬',mapmenu:'지도 메뉴'};
