function essence(){const open=essenceSlotsFor(state.player.level),equipped=state.equippedEssences||[];return `<section><div class="section-title"><div><small>ESSENCE SLOTS</small><h3>장착 정수 <em>${equipped.length} / ${open}</em></h3></div></div><div class="essence-slots">${Array.from({length:15},(_,i)=>{const it=equipped[i],locked=i>=open;return `<button class="essence-slot ${locked?'locked':it?'filled':''}" ${locked?'disabled':''} data-essence-slot="${i}"><span>${locked?'🔒':i+1}</span><strong>${locked?'Lv.'+(i*3+1):it?esc(it.name):'빈 슬롯'}</strong>${it?grade(it.grade):''}</button>`}).join('')}</div></section><section class="lower-section"><div class="section-title"><div><small>OWNED ESSENCES</small><h3>보유 정수</h3></div></div>${cards(state.essences,'보유 정수가 없습니다.')}</section>`}
function trait(){const t=state.player.trait||{};return `<article class="trait-panel"><small>HUMAN GROWTH</small><h2>${esc(t.title||'아직 개화하지 않음')}</h2><p>${esc(t.description||'인간족 고유의 가능성이 아직 모습을 드러내지 않았습니다.')}</p><div class="mastery"><span>특성 숙련도</span><b>${Number(t.mastery)||0}${Number(t.maxMastery)>0?` / ${Number(t.maxMastery)}`:''}</b></div><small class="readonly">게임 진행에 따라 CHRONICLE만 갱신할 수 있습니다.</small></article>`}
function derivedSkills(){const essences=state.equippedEssences||[],active=essences.flatMap(e=>e.activeSkills||e.active||[]),passive=essences.flatMap(e=>e.passiveSkills||e.passive||[]);for(const bonus of activeSetBonuses())passive.push(...(bonus.passiveSkills||bonus.skills||[]).map(s=>typeof s==='string'?{name:s,description:`${bonus.setName} 세트 효과`}:{...s,source:s.source||`${bonus.setName} 세트`}));return{active,passive}}
function skills(){const{active,passive}=derivedSkills(),list=(a,empty,kind)=>a.length?`<div class="skill-list">${a.map((s,i)=>{const x=typeof s==='string'?{name:s}:s;return `<button class="skill-card" data-skill="${i}" data-skill-kind="${kind}"><strong>${esc(x.name||x.title||'스킬')}</strong><small>${esc(x.description||'')}</small></button>`}).join('')}</div>`:`<div class="empty-card">${empty}</div>`;return `<div class="skill-columns"><section><div class="section-title"><div><small>ACTIVE</small><h3>액티브 스킬</h3></div></div>${list(active,'장착 정수에서 얻은 액티브 스킬이 없습니다.','active')}</section><section><div class="section-title"><div><small>PASSIVE</small><h3>패시브 스킬</h3></div></div>${list(passive,'장착 정수와 장비 세트에서 얻은 패시브 스킬이 없습니다.','passive')}</section></div>`}
function statTotals(){const base={...BASE_STATS,...state.player.stats},gear={},essenceBonus={},setBonus={},special={...SPECIAL_DEFAULTS,...state.player.specialStats},specialGear={},specialEssence={},specialSet={};for(const it of Object.values(state.equipped||{})){for(const[k,v]of Object.entries(it?.stats||{}))gear[k]=(gear[k]||0)+(Number(v)||0);for(const[k,v]of Object.entries(it?.specialStats||{}))specialGear[k]=(specialGear[k]||0)+(Number(v)||0)}for(const it of state.equippedEssences||[]){for(const[k,v]of Object.entries(it?.stats||{}))essenceBonus[k]=(essenceBonus[k]||0)+(Number(v)||0);for(const[k,v]of Object.entries(it?.specialStats||{}))specialEssence[k]=(specialEssence[k]||0)+(Number(v)||0)}for(const bonus of activeSetBonuses()){for(const[k,v]of Object.entries(bonus.stats||{}))setBonus[k]=(setBonus[k]||0)+(Number(v)||0);for(const[k,v]of Object.entries(bonus.specialStats||{}))specialSet[k]=(specialSet[k]||0)+(Number(v)||0)}const final={},specialFinal={};for(const k of Object.keys(STAT_INFO))final[k]=(base[k]||0)+(gear[k]||0)+(essenceBonus[k]||0)+(setBonus[k]||0);for(const k of Object.keys(SPECIAL_INFO))specialFinal[k]=(special[k]||0)+(specialGear[k]||0)+(specialEssence[k]||0)+(specialSet[k]||0);return{base,gear,essenceBonus,setBonus,final,special,specialGear,specialEssence,specialSet,specialFinal}}
function recalculateResources(){const p=state?.player;if(!p)return;const vitality=Math.max(0,Number(statTotals().final.vitality)||0),extra=Math.max(0,vitality-5),oldHpMax=Math.max(1,Number(p.maxHp)||100),oldSpMax=Math.max(1,Number(p.maxSp)||100);if(!p.resourceFormula)p.resourceFormula={baseHp:Math.max(1,oldHpMax-extra*5),baseSp:Math.max(1,oldSpMax-extra*3),hpPerVitality:5,spPerVitality:3};const f=p.resourceFormula,nextHp=Math.max(1,Math.round((Number(f.baseHp)||100)+extra*(Number(f.hpPerVitality)||5))),nextSp=Math.max(1,Math.round((Number(f.baseSp)||100)+extra*(Number(f.spPerVitality)||3)));if(nextHp!==oldHpMax)p.hp=Math.max(0,Math.min(nextHp,Math.round((Number(p.hp)||0)/oldHpMax*nextHp)));if(nextSp!==oldSpMax)p.sp=Math.max(0,Math.min(nextSp,Math.round((Number(p.sp)||0)/oldSpMax*nextSp)));p.maxHp=nextHp;p.maxSp=nextSp}
function stats(){const t=statTotals(),initial=state.player.initialStats||{},level=state.player.statGrowth?.level||{},chronicle=state.player.statGrowth?.chronicle||{},sections=state.settings.statSections||{base:true,special:true},baseRows=Object.entries(STAT_INFO).map(([k,x])=>{const bonus=(t.gear[k]||0)+(t.essenceBonus[k]||0)+(t.setBonus[k]||0);return `<article class="stat-row"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span>초기 ${initial[k]??BASE_STATS[k]??0}</span><span>레벨 +${level[k]||0}</span><span>진행 +${chronicle[k]||0}</span><span>장비·정수·세트 ${bonus>=0?'+':''}${bonus}</span><b>${t.final[k]||0}</b></article>`}).join(''),specialRows=Object.entries(SPECIAL_INFO).map(([k,x])=>{const bonus=(t.specialGear[k]||0)+(t.specialEssence[k]||0)+(t.specialSet[k]||0);return `<article class="special-stat-row"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span>기본 ${t.special[k]||0}%</span><span>장비·정수·세트 ${bonus>=0?'+':''}${bonus}%</span><b>${t.specialFinal[k]||0}%</b></article>`}).join('');return `<div class="stat-screen"><p class="stat-note">확정 스탯은 생성·레벨 성장·CHRONICLE 진행이 누적되며 장비·정수·세트 보정이 더해집니다.</p><section class="stat-section"><button class="stat-section-toggle" data-stat-section="base"><span>기본 스탯</span><i>${sections.base?'−':'＋'}</i></button><div class="stat-section-body ${sections.base?'':'hidden'}">${baseRows}</div></section><section class="stat-section"><button class="stat-section-toggle" data-stat-section="special"><span>특수 스탯</span><i>${sections.special?'−':'＋'}</i></button><div class="stat-section-body ${sections.special?'':'hidden'}">${specialRows}</div></section></div>`}
function inventory(){return state.inventory.length?`<div class="drawer-grid">${state.inventory.map(x=>`<button class="data-card inventory-card" data-inventory="${esc(x.id)}">${grade(x.grade)}<strong>${esc(x.name)}</strong><small>${esc(x.type)} · ${Number(x.quantity)||1}개</small><p>${esc(x.description||'설명 없음')}</p></button>`).join('')}</div>`:'<div class="empty-card">소지품이 없습니다.</div>'}
function ruleReminderDue(){const r=state.settings.ruleReminder||{},byCommands=(Number(r.commandCount)||0)-(Number(r.lastCommandCount)||0)>=Math.max(10,Number(r.minimumCommands)||30),byTime=Date.now()-(Number(r.lastAt)||0)>=Math.max(86400000,Number(r.minIntervalMs)||604800000);return byCommands&&byTime}
function buildRuleReminder(){const gm=state.settings.gmRules?.trim(),sheet=state.settings.sheetRules?.trim();if(!gm&&!sheet)return'';return `CHRONICLE 진행 규칙을 다시 확인해 주세요. 아래 규칙은 요약하거나 임의로 변경하지 말고 이후 진행에 적용합니다.\n\n[GM 진행 규칙]\n${gm||'저장된 규칙 없음'}\n\n[Google Sheets 연결 규칙]\n${sheet||'저장된 규칙 없음'}`}
function consumeRuleReminder(force=false){if(!force&&!ruleReminderDue())return null;const prompt=buildRuleReminder();if(!prompt)return null;const r=state.settings.ruleReminder;r.lastAt=Date.now();r.lastCommandCount=Number(r.commandCount)||0;save(false);return prompt}
function content(tab){if(tab==='people')return people();if(tab==='equipment')return equipment();if(tab==='essence')return essence();if(tab==='stats')return stats();if(tab==='trait')return trait();if(tab==='skills')return skills();if(tab==='inventory')return inventory();if(tab==='settings'){const sync=state.settings.sheetSync||{};return `<div class="settings-stack"><label class="setting-card"><strong>ChatGPT 채팅방 링크</strong><small>추후 CHRONICLE 버튼에서 ChatGPT를 사이드로 실행할 때 사용합니다.</small><input id="chatgptUrl" type="url" placeholder="https://chatgpt.com/..." value="${esc(state.settings?.chatgptUrl||'')}"><button class="primary" id="saveChatgptUrl">링크 저장</button></label><label class="setting-card"><strong>이미지 생성용 GPT 링크</strong><small>프로필 이미지 프롬프트를 복사한 뒤 자동으로 이동할 GPT 주소입니다.</small><input id="imageGptUrl" type="url" placeholder="https://chatgpt.com/g/..." value="${esc(state.settings?.imageGptUrl||'')}"><button class="primary" id="saveImageGptUrl">이미지 GPT 링크 저장</button></label><section class="setting-card rule-settings"><strong>GM 규칙 상기</strong><small>규칙은 저장만 해두고 최소 30개의 상태 명령과 7일이 모두 지난 경우에만 자동 연동 API가 상기하도록 설계되어 있습니다.</small><label>GM 진행 규칙<textarea id="gmRules" rows="7" placeholder="GM의 진행 원칙과 세계관 규칙">${esc(state.settings.gmRules||'')}</textarea></label><label>Google Sheets 연결 규칙<textarea id="sheetRules" rows="7" placeholder="시트 명령 작성과 동기화 규칙">${esc(state.settings.sheetRules||'')}</textarea></label><button class="primary" id="saveRulePrompts">규칙 저장</button><button class="secondary-rule" id="copyRuleReminder">지금 상기 프롬프트 복사</button><small>${ruleReminderDue()?'간헐적 상기 조건 충족':'상기 대기 중 · 잦은 반복 방지 적용'}</small></section><article class="setting-card sync-card"><strong>Google Sheets 명령 중계</strong><small>TRPG_COMMANDS 탭의 새 명령을 4초마다 확인해 현재 캐릭터에 반영합니다.</small><a href="https://docs.google.com/spreadsheets/d/${SHEET_SYNC.sheetId}/edit" target="_blank" rel="noopener">연결된 시트 열기</a><div><span>상태</span><b id="sheetSyncStatus">${esc(sync.lastResult||'연결 대기 중')}</b></div><button class="primary" id="syncSheetNow">지금 동기화</button></article></div>`}return '<div class="empty-card">현재 위치, 지역 정보와 지도 표시 옵션 영역입니다.</div>'}
function setData(item){if(!item?.set&&!item?.setId)return null;const raw=item.set||{};return{id:raw.id||item.setId,name:raw.name||item.setName||'이름 없는 세트',description:raw.description||item.setDescription||'',bonuses:raw.bonuses||item.setBonuses||[]}}
function equippedSetState(){const groups={};for(const [slot,item] of Object.entries(state.equipped||{})){const set=setData(item);if(!set?.id)continue;groups[set.id]??={set,count:0,slots:new Set(),items:[]};if(!groups[set.id].slots.has(slot)){groups[set.id].slots.add(slot);groups[set.id].count++;groups[set.id].items.push(item)}}return Object.values(groups)}
function activeSetBonuses(){return equippedSetState().flatMap(g=>(g.set.bonuses||[]).filter(b=>g.count>=Number(b.required||b.pieces||0)).map(b=>({...b,setId:g.set.id,setName:g.set.name,equipped:g.count})))}
function setPanel(item){const set=setData(item);if(!set)return'';const equipped=equippedSetState().find(x=>x.set.id===set.id)?.count||0;return `<section class="set-panel"><small>EQUIPMENT SET</small><h3>${esc(set.name)} <span>${equipped}개 장착</span></h3>${set.description?`<p>${esc(set.description)}</p>`:''}<div>${(set.bonuses||[]).map(b=>`<article class="${equipped>=Number(b.required||b.pieces||0)?'active':''}"><b>${Number(b.required||b.pieces||0)}세트</b><span>${esc(b.description||[...Object.entries(b.stats||{}).map(([k,v])=>`${STAT_INFO[k]?.[0]||k} ${v>=0?'+':''}${v}`),...Object.entries(b.specialStats||{}).map(([k,v])=>`${SPECIAL_INFO[k]?.[0]||k} ${v>=0?'+':''}${v}%`)].join(' · ')||'특수 효과')}</span></article>`).join('')}</div></section>`}
function detail(item,actions=''){const skills=(type,label)=>(item[type]||[]).length?`<div><b>${label}</b><p>${(item[type]||[]).map(x=>esc(typeof x==='string'?x:x.name||x.title)).join(', ')}</p></div>`:'';$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 목록</button><article class="detail-card">${grade(item.grade)}<h2>${esc(item.name)}</h2><p>${esc(item.description||'설명 없음')}</p><div class="stat-list">${statsText(item.stats)}</div>${skills('activeSkills','액티브')}${skills('passiveSkills','패시브')}${setPanel(item)}<div class="actions">${actions}</div></article>`;$('#detailBack').onclick=()=>showTab(activeTab)}
function compare(next,current,confirmLabel){const keys=[...new Set([...Object.keys(current?.stats||{}),...Object.keys(next?.stats||{})])];return `<div class="compare"><div><small>현재</small><b>${esc(current?.name||'없음')}</b></div><span>→</span><div><small>변경</small><b>${esc(next.name)}</b></div></div><div class="stat-list">${keys.map(k=>`<span>${esc(k)}</span><b>${current?.stats?.[k]??0} → ${next.stats?.[k]??0}</b>`).join('')}</div><button class="primary" id="confirmMove">${confirmLabel}</button>`}
function equip(item,slot){const current=state.equipped[slot];$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><h3>${esc(slot)} 장착 확인</h3>${compare(item,current,'장착 확정')}`;$('#detailBack').onclick=()=>showTab('equipment');$('#confirmMove').onclick=()=>{state.equipment=state.equipment.filter(x=>x.id!==item.id);if(current)state.equipment.push(current);state.equipped[slot]=item;save()}}
function bindModal(tab){if(tab==='people')bindPeople();if(tab==='equipment')bindEquipment();if(tab==='essence')bindEssence();if(tab==='stats')document.querySelectorAll('[data-stat-section]').forEach(b=>b.onclick=()=>{const k=b.dataset.statSection;state.settings.statSections[k]=!state.settings.statSections[k];save(false);showTab('stats')});if(tab==='skills')document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const lists=derivedSkills(),list=b.dataset.skillKind==='active'?lists.active:lists.passive,raw=list[Number(b.dataset.skill)],item=typeof raw==='string'?{name:raw}:raw;detail({...item,name:item?.name||item?.title||'스킬',grade:item?.grade||'일반',stats:item?.stats||{}})});if(tab==='settings'){const storeUrl=(input,key,message)=>{const v=$(input).value.trim();if(v){try{const u=new URL(v);if(!['http:','https:'].includes(u.protocol))throw 0}catch{return alert('올바른 http/https 링크를 입력해 주세요.')}}state.settings[key]=v;save(false);alert(message)};$('#saveChatgptUrl').onclick=()=>storeUrl('#chatgptUrl','chatgptUrl','ChatGPT 채팅방 링크를 저장했습니다.');$('#saveImageGptUrl').onclick=()=>storeUrl('#imageGptUrl','imageGptUrl','이미지 생성용 GPT 링크를 저장했습니다.');$('#saveRulePrompts').onclick=()=>{state.settings.gmRules=$('#gmRules').value.trim();state.settings.sheetRules=$('#sheetRules').value.trim();save(false);alert('GM 규칙과 시트 연결 규칙을 저장했습니다.')};$('#copyRuleReminder').onclick=()=>{state.settings.gmRules=$('#gmRules').value.trim();state.settings.sheetRules=$('#sheetRules').value.trim();const prompt=consumeRuleReminder(true);if(!prompt)return alert('먼저 상기할 규칙을 입력해 주세요.');copyText(prompt).then(ok=>alert(ok?'규칙 상기 프롬프트를 복사했습니다.':'클립보드 복사에 실패했습니다.'))};$('#syncSheetNow').onclick=()=>syncSheetCommands(true)}if(tab==='inventory')document.querySelectorAll('[data-inventory]').forEach(b=>b.onclick=()=>showInventoryDetail(b.dataset.inventory))}
function showInventoryDetail(id){const item=state.inventory.find(x=>x.id===id);if(!item)return showTab('inventory');$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 소지품 목록</button><article class="detail-card inventory-detail">${grade(item.grade)}<h2>${esc(item.name)}</h2><div class="item-meta"><span>${esc(item.type)}</span><b>${Number(item.quantity)||1}개</b></div><p>${esc(item.description||'설명 없음')}</p>${item.effect?`<div class="item-effect">✦ ${esc(item.effect)}</div>`:''}${item.usable?'<button class="primary" id="useInventoryItem">사용</button>':'<small class="readonly">현재 직접 사용할 수 없는 소지품입니다.</small>'}</article>`;$('#detailBack').onclick=()=>showTab('inventory');$('#useInventoryItem')?.addEventListener('click',()=>{const result=window.TRPGWindow.useInventoryItem(item.id);if(result.ok)showTab('inventory')})}
function bindPeople(){$('#addCharacter').onclick=()=>{$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><form id="characterForm" class="form-card"><label>이름<input name="name" required></label><label>간단 소개<textarea name="introduction" rows="3"></textarea></label><label>고정 외형 특성<textarea name="appearance" rows="4" placeholder="머리색, 눈동자, 인상, 체형, 흉터, 복장 등"></textarea></label><label>장기기억<textarea name="longMemory" rows="7"></textarea></label><button class="primary">추가</button></form>`;$('#detailBack').onclick=()=>showTab('people');$('#characterForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.characters.push({id:uid('character'),name:f.get('name').trim(),introduction:f.get('introduction').trim(),appearance:f.get('appearance').trim(),longMemory:f.get('longMemory').trim(),portrait:'',updatedAt:Date.now(),source:'user'});save()}};document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{const c=state.characters.find(x=>x.id===b.dataset.memory);$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 목록</button><form id="memoryForm" class="form-card"><h3>${esc(c.name)} · 장기기억</h3><textarea name="memory" rows="12">${esc(c.longMemory||'')}</textarea><button class="primary">저장</button></form>`;$('#detailBack').onclick=()=>showTab('people');$('#memoryForm').onsubmit=e=>{e.preventDefault();c.longMemory=new FormData(e.currentTarget).get('memory').trim();c.updatedAt=Date.now();save()}});document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openPortraitSetup('character',b.dataset.photo))}
function portraitSubject(kind,id){if(kind==='player')return state.player;return state.characters.find(c=>c.id===id)}
function portraitAppearance(kind,subject){if(kind==='player')return subject.appearance||subject.character?.appearance||'';return subject.appearance||''}
function portraitPrompt(kind,subject,appearance){const role=kind==='player'?'플레이어 캐릭터':'등장인물';return `중세 판타지 TRPG의 ${role} 프로필 초상화를 제작해 주세요.\n\n인물 이름: ${subject.name||'이름 없음'}\n고정 외형 특성: ${appearance||'아직 구체적으로 정해지지 않음'}\n보조 정보: ${subject.introduction||subject.title||''}\n\n표현 지침:\n- 낡고 은은한 양피지 배경\n- 고전 중세 판타지 삽화와 사실적인 회화가 섞인 분위기\n- 얼굴과 상반신 중심의 정면 또는 살짝 비스듬한 구도\n- 외형 특성을 빠뜨리거나 임의로 변경하지 말 것\n- 차분한 갈색·금색 계열, 섬세한 잉크선과 부드러운 명암\n- 글자, 문장, 로고, 테두리는 이미지에 넣지 말 것\n- 정사각형 1:1 비율, 원형 프로필로 잘라도 얼굴이 온전히 남는 여백`}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const box=document.createElement('textarea');box.value=text;box.style.position='fixed';box.style.opacity='0';document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();return ok}}
function openPortraitSetup(kind,id=''){const subject=portraitSubject(kind,id);if(!subject)return;activeTab=kind==='player'?'playerProfile':'people';$('#modalTitle').textContent=kind==='player'?'내 프로필':'인물 프로필';const appearance=portraitAppearance(kind,subject);$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← ${kind==='player'?'닫기':'인물 목록'}</button><section class="portrait-settings"><div class="portrait-preview">${subject.portrait?`<img src="${esc(subject.portrait)}" alt="${esc(subject.name)}">`:`<span>${esc((subject.name||'?')[0])}</span>`}</div><h2>${esc(subject.name||'이름 없음')}</h2><label>고정 외형 특성<textarea id="portraitAppearance" rows="5" placeholder="머리색, 눈동자, 인상, 체형, 흉터, 복장 등">${esc(appearance)}</textarea></label><div class="portrait-actions"><button id="generatePortraitPrompt">✦ 이미지 생성</button><button id="importPortrait">▣ 이미지 불러오기</button></div><small>이미지 생성은 프롬프트를 복사하고 설정된 이미지 생성용 GPT를 엽니다.</small><input id="portraitImportFile" type="file" accept="image/png,image/jpeg,image/webp" hidden></section>`;$('#detailBack').onclick=()=>kind==='player'?closeModal():showTab('people');const updateAppearance=()=>{const value=$('#portraitAppearance').value.trim();if(kind==='player'){subject.appearance=value;subject.character={...(subject.character||{}),appearance:value}}else subject.appearance=value;subject.updatedAt=Date.now();save(false);return value};$('#generatePortraitPrompt').onclick=()=>{const prompt=portraitPrompt(kind,subject,updateAppearance()),url=state.settings.imageGptUrl,opened=url?window.open(url,'_blank','noopener'):null;copyText(prompt).then(ok=>alert(ok?(url?'이미지 프롬프트를 복사하고 이미지 생성용 GPT를 열었습니다.':'이미지 프롬프트를 복사했습니다. 설정에서 이미지 생성용 GPT 링크를 저장해 주세요.'):'프롬프트 복사에 실패했습니다.'));if(url&&!opened)alert('팝업이 차단되었습니다. 설정에 저장된 링크를 직접 열어 주세요.')};const input=$('#portraitImportFile');$('#importPortrait').onclick=()=>input.click();input.onchange=()=>{const file=input.files?.[0];if(!file)return;updateAppearance();const reader=new FileReader();reader.onload=()=>cropPortrait(kind,id,String(reader.result));reader.readAsDataURL(file)}}
function cropPortrait(kind,id,src){$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><div class="crop-wrap"><h3>원형 프로필 맞추기</h3><div class="crop-stage" id="cropStage"><img id="cropImage" src="${esc(src)}" alt=""><div class="crop-mask"></div></div><label>확대<input id="cropZoom" type="range" min="1" max="3" step=".01" value="1"></label><button class="primary" id="cropSave">이대로 저장</button></div>`;$('#detailBack').onclick=()=>openPortraitSetup(kind,id);const stage=$('#cropStage'),img=$('#cropImage'),zoom=$('#cropZoom');let scale=1,x=0,y=0,drag=false,sx=0,sy=0,bx=0,by=0;const draw=()=>img.style.transform=`translate(${x}px,${y}px) scale(${scale})`;zoom.oninput=()=>{scale=Number(zoom.value);draw()};stage.onpointerdown=e=>{drag=true;sx=e.clientX;sy=e.clientY;bx=x;by=y;stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(drag){x=bx+e.clientX-sx;y=by+e.clientY-sy;draw()}};stage.onpointerup=stage.onpointercancel=()=>drag=false;$('#cropSave').onclick=()=>{const source=new Image();source.onload=()=>{const size=512,cv=document.createElement('canvas'),ctx=cv.getContext('2d');cv.width=cv.height=size;const base=Math.max(size/source.naturalWidth,size/source.naturalHeight)*scale,w=source.naturalWidth*base,h=source.naturalHeight*base,ratio=size/stage.clientWidth;ctx.beginPath();ctx.arc(size/2,size/2,size/2,0,Math.PI*2);ctx.clip();ctx.drawImage(source,(size-w)/2+x*ratio,(size-h)/2+y*ratio,w,h);const subject=portraitSubject(kind,id);if(subject){subject.portrait=cv.toDataURL('image/jpeg',.88);subject.updatedAt=Date.now();save(false);if(kind==='player')$('#playerAvatar').innerHTML=`<img src="${esc(subject.portrait)}" alt="${esc(subject.name)}">`;openPortraitSetup(kind,id)}};source.src=src}}
function bindEquipment(){document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const item=state.equipment.find(x=>x.id===b.dataset.item);detail(item,`<button class="primary" id="equipOwned">장착</button>`);$('#equipOwned').onclick=()=>{$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><h3>장착 부위 선택</h3><div class="slot-grid">${SLOTS.map(s=>`<button class="slot" data-pick-slot="${s}"><small>${s}</small><strong>${esc(state.equipped[s]?.name||'비어 있음')}</strong></button>`).join('')}</div>`;$('#detailBack').onclick=()=>showTab('equipment');document.querySelectorAll('[data-pick-slot]').forEach(x=>x.onclick=()=>equip(item,x.dataset.pickSlot))}});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{const slot=b.dataset.slot,item=state.equipped[slot];if(!item)return;if(!state.equipment.length)return detail(item,`<button class="unequip-button" id="unequip">해제</button>`);detail(item,`<button class="primary equipment-action" id="changeEquip">변경</button><button class="unequip-button equipment-action" id="unequip">해제</button>`);$('#unequip').onclick=()=>{state.equipment.push(item);delete state.equipped[slot];save()};$('#changeEquip').onclick=()=>{$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><h3>${esc(slot)} 변경 장비 선택</h3>${cards(state.equipment,'변경할 장비가 없습니다.')}`;$('#detailBack').onclick=()=>showTab('equipment');document.querySelectorAll('[data-item]').forEach(x=>x.onclick=()=>equip(state.equipment.find(v=>v.id===x.dataset.item),slot))}})}
function bindEssence(){document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const item=state.essences.find(x=>x.id===b.dataset.item),hasRoom=state.equippedEssences.length<essenceSlotsFor(state.player.level);detail(item,hasRoom?'<button class="primary" id="equipEssence">빈 슬롯에 장착</button>':'<small>열린 빈 슬롯이 없습니다.</small>');const equipButton=$('#equipEssence');if(equipButton)equipButton.onclick=()=>{state.essences=state.essences.filter(x=>x.id!==item.id);state.equippedEssences.push(item);save()}});document.querySelectorAll('[data-essence-slot]').forEach(b=>b.onclick=()=>{const item=state.equippedEssences[Number(b.dataset.essenceSlot)];if(item)detail(item,'<small>장착한 정수는 UI에서 해제·교체·삭제할 수 없습니다.</small>')})}
const BACKGROUNDS={commoner:{name:'평민',mods:{vitality:1},gold:40},artisan:{name:'장인 가문',mods:{strength:1,intelligence:1},gold:30},merchant:{name:'상인 가문',mods:{intelligence:1,luck:1},gold:80},minor_noble:{name:'하급 귀족',mods:{intelligence:1,will:1},gold:120},frontier:{name:'변경 출신',mods:{vitality:1,will:1},gold:25},orphan:{name:'고아',mods:{agility:1,luck:1},gold:10},wanderer:{name:'방랑자',mods:{will:1,luck:1},gold:20},custom:{name:'직접 작성',mods:{},gold:30}};
function homeOverlay(html){let o=$('#homeOverlay');if(!o){o=document.createElement('div');o.id='homeOverlay';document.body.append(o)}o.innerHTML=html;return o}
function showHome(){const saves=allSaves(),count=Object.keys(saves).length;homeOverlay(`<section class="home-screen"><div class="home-crest">✦</div><small>CHRONICLE · PLAY VERSION 0.0.1</small><h1>TRPG WINDOW</h1><p>아직 쓰이지 않은 연대기의 다음 장.<br>당신의 선택이 세계의 기억이 됩니다.</p><div class="home-actions"><button class="home-primary" id="homeNew"><b>새로 만들기</b><span>새로운 인간족 모험가를 생성합니다</span></button><button id="homeContinue" ${count?'':'disabled'}><b>이어하기</b><span>${count?`${count}개의 연대기`:'저장된 캐릭터 없음'}</span></button><button id="homeExport" ${activeSaveId?'':'disabled'}><b>JSON 내보내기</b><span>현재 캐릭터 저장</span></button><button id="homeImport"><b>JSON 불러오기</b><span>저장 파일 가져오기</span></button></div><footer>THE CHRONICLE REMEMBERS EVERY CHOICE</footer></section>`);$('#homeNew').onclick=()=>creator(0,{name:'',sex:'남성',age:20,height:170,build:'보통',appearance:'',background:null,backgroundNote:'',statAlloc:Object.fromEntries(STAT_KEYS.map(k=>[k,5]))});$('#homeContinue').onclick=showContinue;$('#homeExport').onclick=exportSave;$('#homeImport').onclick=()=>$('#saveImportInput').click()}
function showContinue(){const saves=allSaves(),rows=Object.entries(saves).sort((a,b)=>(b[1]._savedAt||0)-(a[1]._savedAt||0));homeOverlay(`<section class="home-screen continue-screen"><button class="home-back" id="homeBack">← 홈</button><small>SAVED CHRONICLES</small><h2>이어할 캐릭터 선택</h2><div class="save-list">${rows.map(([id,s])=>`<article><button data-load-save="${esc(id)}"><b>${esc(s.player?.name||'이름 없음')}</b><span>Lv.${s.player?.level||1} · ${esc(s.player?.title||'모험가')}</span><small>${esc(s.location||'장소 미정')}</small></button><button class="save-delete" data-delete-save="${esc(id)}">삭제</button></article>`).join('')}</div></section>`);$('#homeBack').onclick=showHome;document.querySelectorAll('[data-load-save]').forEach(b=>b.onclick=()=>{activeSaveId=b.dataset.loadSave;localStorage.setItem(ACTIVE_KEY,activeSaveId);state=merge(clone(defaults),allSaves()[activeSaveId]);$('#homeOverlay').remove();render()});document.querySelectorAll('[data-delete-save]').forEach(b=>b.onclick=()=>{const s=allSaves(),item=s[b.dataset.deleteSave];if(!confirm(`'${item?.player?.name||'이름 없음'}' 캐릭터 저장을 삭제할까요?`))return;delete s[b.dataset.deleteSave];writeSaves(s);if(activeSaveId===b.dataset.deleteSave){activeSaveId='';localStorage.removeItem(ACTIVE_KEY);state=clone(defaults)}showContinue()})}
function pointsLeft(d){return 12-STAT_KEYS.reduce((n,k)=>n+(Number(d.statAlloc[k]||5)-5),0)}
function creator(step,d){const progress=`<div class="creator-progress"><small>CHARACTER CREATION</small><span>${step+1} / 4</span></div>`,nav=(back,next,label='다음 ›')=>`<div class="creator-nav"><button id="creatorBack">${back}</button><button class="primary" id="creatorNext" ${next?'':'disabled'}>${label}</button></div>`;let body='';if(step===0)body=`${progress}<h2>누구의 연대기를 시작할까요?</h2><div class="selected-race"><small>PLAYER RACE</small><b>인간</b><p>종족 능력치 보정 없이 어떤 성장 방향에도 제약이 없습니다. 인간족은 진행에 따라 고유 특성이 개화합니다.</p></div><label>이름<input id="ccName" value="${esc(d.name)}" placeholder="캐릭터 이름"></label>${nav('‹ 홈',!!d.name.trim())}`;if(step===1)body=`${progress}<h2>어떤 모습으로 살아가나요?</h2><div class="form-grid"><label>성별<select id="ccSex"><option>남성</option><option>여성</option><option>직접 작성</option></select></label><label>나이<input id="ccAge" type="number" min="1" value="${d.age}"></label><label>키(cm)<input id="ccHeight" type="number" min="50" value="${d.height}"></label><label>체형<select id="ccBuild"><option>마른</option><option>보통</option><option>탄탄한</option><option>건장한</option><option>거대한</option></select></label></div><label>외형 특징<textarea id="ccAppearance" rows="4">${esc(d.appearance)}</textarea></label>${nav('‹ 이전',true)}`;if(step===2)body=`${progress}<h2>어떤 삶을 살아왔나요?</h2><div class="background-grid">${Object.entries(BACKGROUNDS).map(([id,x])=>`<button class="background-card ${d.background===id?'selected':''}" data-background="${id}"><b>${x.name}</b><span>시작 골드 ${x.gold} G</span><small>${Object.entries(x.mods).map(([k,v])=>`${STAT_INFO[k][0]} +${v}`).join(' · ')||'능력치 보정 없음'}</small></button>`).join('')}</div><label>추가 배경<textarea id="ccBackgroundNote" rows="4">${esc(d.backgroundNote)}</textarea></label>${nav('‹ 이전',!!d.background)}`;if(step===3){const left=pointsLeft(d);body=`${progress}<h2>어떤 재능을 타고났나요?</h2><p class="creator-hint">기본 5에서 12포인트를 배분합니다. 이 수치는 앞으로의 자동 성장 확률에도 사용됩니다.</p><div class="points-left">남은 포인트 <b>${left}</b> / 12</div><div class="stat-alloc">${STAT_KEYS.map(k=>`<div><span>${STAT_INFO[k][0]}</span><button data-minus="${k}" ${d.statAlloc[k]<=5?'disabled':''}>−</button><b>${d.statAlloc[k]}</b><button data-plus="${k}" ${left<=0||d.statAlloc[k]>=10?'disabled':''}>＋</button></div>`).join('')}</div><div class="random-actions"><button id="randomStats">🎲 무작위 배분</button><button id="resetStats">초기화</button></div>${nav('‹ 이전',left===0,'모험 시작')}`}homeOverlay(`<section class="creator-screen">${body}</section>`);bindCreator(step,d)}
function readBody(d){d.sex=$('#ccSex').value;d.age=Math.max(1,Number($('#ccAge').value)||20);d.height=Math.max(50,Number($('#ccHeight').value)||170);d.build=$('#ccBuild').value;d.appearance=$('#ccAppearance').value.trim()}
function bindCreator(step,d){if(step===0){$('#ccName').oninput=e=>{$('#creatorNext').disabled=!e.target.value.trim()};$('#creatorBack').onclick=showHome;$('#creatorNext').onclick=()=>{d.name=$('#ccName').value.trim();if(d.name)creator(1,d)}}if(step===1){$('#ccSex').value=d.sex;$('#ccBuild').value=d.build;$('#creatorBack').onclick=()=>{readBody(d);creator(0,d)};$('#creatorNext').onclick=()=>{readBody(d);creator(2,d)}}if(step===2){document.querySelectorAll('[data-background]').forEach(b=>b.onclick=()=>{d.backgroundNote=$('#ccBackgroundNote').value;d.background=b.dataset.background;creator(2,d)});$('#creatorBack').onclick=()=>{d.backgroundNote=$('#ccBackgroundNote').value;creator(1,d)};$('#creatorNext').onclick=()=>{d.backgroundNote=$('#ccBackgroundNote').value.trim();creator(3,d)}}if(step===3){const rerender=()=>creator(3,d);document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{if(d.statAlloc[b.dataset.minus]>5)d.statAlloc[b.dataset.minus]--;rerender()});document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{if(pointsLeft(d)>0&&d.statAlloc[b.dataset.plus]<10)d.statAlloc[b.dataset.plus]++;rerender()});$('#randomStats').onclick=()=>{d.statAlloc=Object.fromEntries(STAT_KEYS.map(k=>[k,5]));for(let i=0;i<12;i++){const keys=STAT_KEYS.filter(k=>d.statAlloc[k]<10),k=keys[Math.floor(Math.random()*keys.length)];d.statAlloc[k]++}rerender()};$('#resetStats').onclick=()=>{d.statAlloc=Object.fromEntries(STAT_KEYS.map(k=>[k,5]));rerender()};$('#creatorBack').onclick=()=>creator(2,d);$('#creatorNext').onclick=()=>finishCharacter(d)}}
function finishCharacter(d){if(pointsLeft(d)!==0||!d.background)return;const bg=BACKGROUNDS[d.background],stats={...d.statAlloc,mana:1};for(const[k,v]of Object.entries(bg.mods))stats[k]+=v;state=clone(defaults);state.player={...state.player,name:d.name,appearance:d.appearance,title:'F급 모험가',stats:{...stats},initialStats:{...stats},growthProfile:{...d.statAlloc},statGrowth:{level:{},chronicle:{}},maxHp:100+Math.max(0,stats.vitality-5)*5,hp:100+Math.max(0,stats.vitality-5)*5,maxSp:100+Math.max(0,stats.vitality-5)*3,sp:100+Math.max(0,stats.vitality-5)*3,character:{created:true,race:'human',raceName:'인간',sex:d.sex,age:d.age,height:d.height,build:d.build,appearance:d.appearance,background:d.background,backgroundName:bg.name,backgroundNote:d.backgroundNote},trait:{title:'',description:'',mastery:0,maxMastery:0}};state.gold=bg.gold;state.records=[{type:'origin',text:`인간으로 태어나 ${bg.name}의 삶을 살아왔다.${d.backgroundNote?' '+d.backgroundNote:''}`}];const start=fixedPlace({regionId:'capital',nodeId:'guild',locationId:'guild',name:'아르켈리온 길드',description:'의뢰·등록·정산과 탐사 정보가 집중되는 왕도 길드 본부.'});state.map.current={regionId:start.regionId,locationId:start.locationId,name:start.name,description:start.description};state.map.view='capital';activeSaveId=uid('character');save();$('#homeOverlay').remove();render()}
function exportSave(){if(!activeSaveId)return;const blob=new Blob([JSON.stringify({version:'0.0.1',state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`trpg-window-${state.player.name||'save'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#saveImportInput').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{const parsed=JSON.parse(await file.text()),incoming=parsed.state||parsed;if(!incoming?.player)throw 0;activeSaveId=uid('character');state=merge(clone(defaults),incoming);save();showHome()}catch{alert('올바른 TRPG Window 세이브 JSON이 아닙니다.')}};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openModal(b.dataset.tab));$('#playerProfileButton').onclick=()=>{if(!activeSaveId)return alert('먼저 캐릭터를 생성하거나 불러와 주세요.');$('#modalBackdrop').classList.remove('hidden');openPortraitSetup('player')};$('#mapMenuBtn').onclick=()=>openModal('mapmenu');$('#closeModal').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target===$('#modalBackdrop'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function setRail(collapsed){$('#sideRail').classList.toggle('collapsed',collapsed);$('.game-shell').classList.toggle('rail-collapsed',collapsed);$('#railToggle').setAttribute('aria-label',collapsed?'메뉴 펼치기':'메뉴 접기');localStorage.setItem(RAIL_KEY,collapsed?'1':'0')}setRail(localStorage.getItem(RAIL_KEY)==='1');$('#railToggle').onclick=()=>setRail(!$('#sideRail').classList.contains('collapsed'));
$('#homeBtn').onclick=showHome;
$('#editBtn').onclick=()=>{const f=$('#editForm'),p=state.player;for(const k of ['name','level','title','exp','hp','maxHp','sp','maxSp'])f[k].value=p[k]??0;f.location.value=state.location;f.gold.value=state.gold||0;f.day.value=state.day;$('#editDialog').showModal()};$('#editForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),old=state.player;state.player={...old,name:f.get('name').trim()||'이름 없음',level:Math.max(1,Math.min(MAX_LEVEL,+f.get('level')||1)),title:f.get('title').trim()||'모험가',exp:Math.max(0,+f.get('exp')||0),hp:Math.max(0,+f.get('hp')||0),maxHp:Math.max(1,+f.get('maxHp')||1),sp:Math.max(0,+f.get('sp')||0),maxSp:Math.max(1,+f.get('maxSp')||1)};state.location=f.get('location').trim()||'장소 미정';state.gold=Math.max(0,+f.get('gold')||0);state.day=Math.max(1,+f.get('day')||1);normalizeExperience();$('#editDialog').close();save()});
$('#grantTestWeapon').onclick=()=>{state.equipment.push(normalItem({id:uid('test_weapon'),name:'연습용 철검',description:'장비 흐름 검증을 위한 테스트 무기입니다.',grade:'희귀',slot:'주무기',stats:{strength:3,agility:1},testItem:true},'equipment'));save(false);alert('보유 장비에 연습용 철검을 지급했습니다.')};$('#grantTestEssence').onclick=()=>{state.essences.push(normalItem({id:uid('test_essence'),name:'메아리의 정수',description:'정수 슬롯과 스킬 파생 검증을 위한 테스트 정수입니다.',grade:'영웅',stats:{will:2,mana:1},activeSkills:[{name:'공명 파동',description:'응축한 공명을 방출합니다.'}],passiveSkills:[{name:'잔향',description:'의지와 마력의 흐름을 강화합니다.'}],testItem:true},'essence'));save(false);alert('보유 정수에 메아리의 정수를 지급했습니다.')};
function pickGrowth(level,point){const p=state.player,weights=STAT_KEYS.map(k=>Math.max(1,Number(p.growthProfile?.[k])||1)),total=weights.reduce((a,b)=>a+b,0);let cursor=((level*17+point*31)%1000)/1000*total;for(let i=0;i<STAT_KEYS.length;i++){cursor-=weights[i];if(cursor<0)return STAT_KEYS[i]}return STAT_KEYS[0]}
function growBase(level){const p=state.player;p.statGrowth??={level:{},chronicle:{}};for(let point=0;point<2;point++){const k=pickGrowth(level,point);p.stats[k]=(Number(p.stats[k])||0)+1;p.statGrowth.level[k]=(p.statGrowth.level[k]||0)+1}if(level%5===0)for(const k of STAT_KEYS){p.stats[k]=(Number(p.stats[k])||0)+1;p.statGrowth.level[k]=(p.statGrowth.level[k]||0)+1}}
function normalizeExperience(){const p=state.player;p.level=Math.max(1,Math.min(MAX_LEVEL,Number(p.level)||1));p.exp=Math.max(0,Number(p.exp)||0);p.levelHistory=Array.isArray(p.levelHistory)?p.levelHistory:[];while(p.level<MAX_LEVEL&&p.exp>=expRequired(p.level)){p.exp-=expRequired(p.level);p.level++;growBase(p.level);p.levelHistory.push({level:p.level,at:Date.now()})}if(p.level>=MAX_LEVEL)p.exp=0;return p.level}
function fixedPlace(payload={}){const regionId=payload.regionId||'capital',locationId=String(payload.locationId||payload.name||uid('place')).trim().toLowerCase().replace(/\s+/g,'_'),existing=state.map.places[locationId];if(existing)return existing;let mapView=payload.mapView||(regionId==='capital'?'capital':regionId==='dungeon'?'dungeon':'continent'),nodes=mapView==='capital'?CAPITAL_NODES:MAP_REGIONS,center=nodes.find(n=>n.id===payload.nodeId||n.id===regionId||n.locationId===regionId)||{x:50,y:50},spread=mapView==='capital'?5:8,x=Math.max(7,Math.min(93,center.x+(Math.random()-.5)*spread*2)),y=Math.max(8,Math.min(92,center.y+(Math.random()-.5)*spread*2)),place={locationId,regionId,mapView,x:Math.round(x*100)/100,y:Math.round(y*100)/100,name:payload.name||locationId,description:payload.description||'',aliases:payload.aliases||[],createdAt:Date.now()};state.map.places[locationId]=place;return place}
function processedCommandIds(){try{return new Set(JSON.parse(localStorage.getItem(SYNC_IDS_KEY)||'[]'))}catch{return new Set()}}
function rememberCommand(id){const ids=processedCommandIds();ids.add(id);localStorage.setItem(SYNC_IDS_KEY,JSON.stringify([...ids].slice(-500)))}
function sheetRows(){return new Promise((resolve,reject)=>{const callback=`trpgSheet_${Date.now()}_${Math.random().toString(36).slice(2)}`,script=document.createElement('script'),timeout=setTimeout(()=>finish(new Error('시트 응답 시간 초과')),12000);function finish(error,value){clearTimeout(timeout);delete window[callback];script.remove();error?reject(error):resolve(value)}window[callback]=response=>{if(response?.status==='error')return finish(new Error(response.errors?.[0]?.message||'시트를 읽을 수 없습니다.'));const table=response?.table||{},headers=(table.cols||[]).map((c,i)=>c.label||`column_${i}`),rows=(table.rows||[]).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r.c?.[i]?.v??''])));finish(null,rows)};script.onerror=()=>finish(new Error('시트가 공개되어 있지 않거나 네트워크 연결을 확인할 수 없습니다.'));script.src=`https://docs.google.com/spreadsheets/d/${SHEET_SYNC.sheetId}/gviz/tq?sheet=${encodeURIComponent(SHEET_SYNC.sheetName)}&headers=1&tqx=out:json;responseHandler:${callback}`;document.head.appendChild(script)})}
function parseCommandPayload(value){if(!value)return{};if(typeof value==='object')return value;try{return JSON.parse(value)}catch{throw new Error('payload_json 형식 오류')}}
function applySheetCommand(command){const payload=parseCommandPayload(command.payload_json),api=window.TRPGWindow,type=String(command.command_type||'').trim().toLowerCase();switch(type){case'set_location':case'location':return api.setLocation(payload);case'upsert_character':case'update_character':case'character':return api.upsertCharacter(payload);case'set_speakers':state.speakers=clone(Array.isArray(payload)?payload:payload.speakers||[]);state.activeSpeakerId=Array.isArray(payload)?'':payload.activeSpeakerId||'';return save();case'grant_equipment':case'equipment':return api.grantEquipment(payload);case'grant_essence':case'essence':return api.grantEssence(payload);case'remove_equipped_essence':return api.removeEquippedEssence(payload.id);case'grant_inventory':case'inventory':return api.grantInventory(payload.item||payload,payload.quantity||1);case'remove_inventory':return api.removeInventory(payload.id,payload.quantity||1);case'award_experience':case'exp':return api.awardExperience(payload.amount??payload.exp??0);case'increase_stats':case'stats':return api.increaseStats(payload.stats||payload,payload.source||'chronicle');case'increase_special_stats':case'special_stats':return api.increaseSpecialStats(payload.stats||payload);case'set_trait':case'trait':return api.setTrait(payload);case'set_state':return api.setState(payload);default:throw new Error(`지원하지 않는 명령: ${type||'(비어 있음)'}`)}}
let sheetSyncRunning=false;
window.CHRONICLE_RULE_REMINDER={isDue:ruleReminderDue,preview:buildRuleReminder,take:consumeRuleReminder};
window.CHRONICLE_SPEAKERS={set(input){state.speakers=clone(Array.isArray(input)?input:input?.speakers||[]);state.activeSpeakerId=Array.isArray(input)?'':input?.activeSpeakerId||'';save();return clone(resolvedSpeakers())},get:()=>clone(resolvedSpeakers())};
async function syncSheetCommands(manual=false){if(sheetSyncRunning||state.settings.sheetSync?.enabled===false)return;sheetSyncRunning=true;try{const rows=await sheetRows(),done=processedCommandIds();let applied=0,failed=0;for(const command of rows){const id=String(command.command_id||'').trim(),status=String(command.status||'pending').trim().toLowerCase(),target=String(command.character_id||'').trim();if(!id||done.has(id)||!['','pending'].includes(status)||target&&target!==activeSaveId)continue;try{applySheetCommand(command);rememberCommand(id);done.add(id);applied++}catch(error){failed++;console.warn('[TRPG Sheet]',id,error)}}if(applied)state.settings.ruleReminder.commandCount=(Number(state.settings.ruleReminder.commandCount)||0)+applied;state.settings.sheetSync.lastSyncAt=Date.now();state.settings.sheetSync.lastResult=failed?`${applied}개 적용 · ${failed}개 오류`:applied?`${applied}개 명령 적용됨`:'새 명령 없음';save(false)}catch(error){state.settings.sheetSync.lastResult=error.message||'동기화 실패';if(manual)alert(state.settings.sheetSync.lastResult)}finally{sheetSyncRunning=false;const status=$('#sheetSyncStatus');if(status)status.textContent=state.settings.sheetSync.lastResult}}
window.TRPGWindow={getState:()=>clone(state),getActiveSetBonuses:()=>clone(activeSetBonuses()),setState(next){state=merge(state,clone(next||{}));normalizeExperience();save()},setSpeakers(speakers){state.speakers=clone(speakers||[]);save()},upsertCharacter(character){const item={id:character.id||uid('character'),name:'이름 없음',introduction:'',longMemory:'',portrait:'',source:'chronicle',...clone(character),updatedAt:Date.now()};const i=state.characters.findIndex(x=>x.id===item.id);i<0?state.characters.push(item):state.characters[i]=item;save();return clone(item)},setTrait(trait){state.player.trait={...state.player.trait,...clone(trait||{})};save()},increaseStats(changes,source='chronicle'){const bucket=source==='level'?'level':'chronicle';state.player.statGrowth??={level:{},chronicle:{}};for(const[k,v]of Object.entries(changes||{})){if(!STAT_INFO[k])continue;const amount=Number(v)||0;state.player.stats[k]=(Number(state.player.stats[k])||0)+amount;state.player.statGrowth[bucket][k]=(state.player.statGrowth[bucket][k]||0)+amount}save();return clone(state.player.stats)},increaseSpecialStats(changes){for(const[k,v]of Object.entries(changes||{})){if(!SPECIAL_INFO[k])continue;state.player.specialStats[k]=(Number(state.player.specialStats[k])||0)+(Number(v)||0)}save();return clone(state.player.specialStats)},setLocation(payload){const place=fixedPlace(clone(payload||{}));state.map.current={regionId:place.regionId,locationId:place.locationId,name:place.name,description:place.description};state.map.view=place.mapView==='capital'?'capital':'continent';state.location=place.name;save();return clone(place)},removeEquippedEssence(id){const i=state.equippedEssences.findIndex(x=>x.id===id);if(i<0)return false;const [item]=state.equippedEssences.splice(i,1);state.essences.push(item);save();return true},grantEquipment(item){state.equipment.push(normalItem(item,'equipment'));save()},grantEssence(item){state.essences.push(normalItem(item,'essence'));save()},grantInventory(item,quantity=1){const next=normalInventory({...item,quantity:Math.max(1,Number(quantity)||1)}),found=state.inventory.find(x=>(next.id&&x.id===next.id)||(!item.id&&x.name===next.name&&x.type===next.type));if(found)found.quantity=(Number(found.quantity)||1)+next.quantity;else state.inventory.push(next);save();return clone(found||next)},removeInventory(id,quantity=1){const item=state.inventory.find(x=>x.id===id);if(!item)return false;item.quantity-=Math.max(1,Number(quantity)||1);if(item.quantity<=0)state.inventory=state.inventory.filter(x=>x.id!==id);save();return true},useInventoryItem(id){const item=state.inventory.find(x=>x.id===id);if(!item||!item.usable)return{ok:false,reason:'not-usable'};const result={ok:true,item:clone(item),effect:item.effect||null};item.quantity-=1;if(item.quantity<=0)state.inventory=state.inventory.filter(x=>x.id!==id);save();return result},awardExperience(amount){const gain=Math.max(0,Math.round(Number(amount)||0));state.player.exp=(Number(state.player.exp)||0)+gain;normalizeExperience();save();return gain},startCombat(enemy){state.combat={active:true,enemy:{...clone(defaults.combat.enemy),...clone(enemy||{})}};save()},endCombat(){state.combat.active=false;save()},reset(){state=clone(defaults);save()},syncNow:()=>syncSheetCommands(true),sync:{sheetId:SHEET_SYNC.sheetId,sheetName:SHEET_SYNC.sheetName,pollMs:SHEET_SYNC.pollMs},rules:{maxLevel:MAX_LEVEL,experience:clone(EXP),expRequired,essenceSlotsFor}};normalizeExperience();save(false);render();showHome();setTimeout(()=>syncSheetCommands(false),1200);setInterval(()=>syncSheetCommands(false),SHEET_SYNC.pollMs);
